using System;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;

// Illustrated shelves use real game data; the side ledger keeps long details paginated.
public sealed class HallShelfCard : Panel {
 public Func<string> Title;public Func<string> Badge;public Func<double> Progress;public Image Portrait;public Rectangle Source;public int Food=-1,Symbol;
 public HallShelfCard(){DoubleBuffered=true;ResizeRedraw=true;Margin=new Padding(5);BackColor=Color.FromArgb(34,64,53);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;var r=Rectangle.Inflate(ClientRectangle,-1,-1);using(var b=new SolidBrush(BackColor))g.FillPolygon(b,GameTheme.Outline(r,6));using(var p=new Pen(Color.FromArgb(151,137,87)))g.DrawPolygon(p,GameTheme.Outline(r,6));
  bool compact=Height<130;int pic=compact?42:72;var box=new Rectangle(8,8,pic,pic);if(Food>=0)FoodCatalog.Icon(g,Food,box);
  else if(Portrait!=null){var src=Source.IsEmpty?new Rectangle(Point.Empty,Portrait.Size):Source;float scale=Math.Min(box.Width/(float)src.Width,box.Height/(float)src.Height);var dst=new Rectangle(box.X+(box.Width-(int)(src.Width*scale))/2,box.Y,(int)(src.Width*scale),(int)(src.Height*scale));g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.NearestNeighbor;g.DrawImage(Portrait,dst,src,GraphicsUnit.Pixel);}
  else DrawSymbol(g,box,Symbol);
  using(var f=GameTheme.Body(11))TextRenderer.DrawText(g,Title==null?"":Title(),f,new Rectangle(box.Right+7,9,Math.Max(20,Width-box.Right-16),compact?26:Math.Max(40,Height-65)),GuildChrome.Ivory,TextFormatFlags.WordBreak|TextFormatFlags.NoPadding|TextFormatFlags.EndEllipsis);
  if(Badge!=null)using(var f=GameTheme.Body(10))TextRenderer.DrawText(g,Badge(),f,new Rectangle(compact?box.Right+7:9,compact?36:Math.Max(box.Bottom+3,Height-60),Width-(compact?box.Right+16:18),22),GuildChrome.Gold,TextFormatFlags.NoPadding|TextFormatFlags.EndEllipsis);
  if(Progress!=null){var track=new Rectangle(10,Height-(compact?14:38),Math.Max(0,Width-110),5);using(var b=new SolidBrush(Color.FromArgb(14,36,29)))g.FillRectangle(b,track);track.Width=(int)(track.Width*Math.Max(0,Math.Min(1,Progress())));using(var b=new SolidBrush(Color.FromArgb(125,183,119)))g.FillRectangle(b,track);}
 }
 static void DrawSymbol(Graphics g,Rectangle r,int kind){int x=r.X,y=r.Y,u=Math.Max(2,r.Width/12);using(var dark=new SolidBrush(Color.FromArgb(92,67,43)))using(var gold=new SolidBrush(Color.FromArgb(202,164,91)))using(var light=new SolidBrush(Color.FromArgb(241,214,152)))using(var green=new SolidBrush(Color.FromArgb(103,153,124))){
  if(kind==0){g.FillRectangle(dark,x+u,y+u*5,u*10,u*5);g.FillRectangle(gold,x,y+u*4,u*12,u*2);g.FillRectangle(light,x+u*2,y+u*2,u*3,u*2);g.FillRectangle(green,x+u*7,y+u,u*3,u*3);}
  else if(kind==1){g.FillRectangle(dark,x+u,y+u*3,u*10,u*8);g.FillRectangle(gold,x,y+u*2,u*12,u*2);g.FillRectangle(light,x+u,y,u*4,u*2);g.FillRectangle(light,x+u*7,y,u*4,u*2);g.FillRectangle(gold,x+u*3,y+u*7,u*2,u*3);g.FillRectangle(gold,x+u*7,y+u*7,u*2,u*3);}
  else if(kind==2){g.FillRectangle(dark,x+u,y+u,u*10,u*10);g.FillRectangle(gold,x,y,u*10,u*10);g.FillRectangle(light,x+u,y+u,u*3,u*8);for(int i=0;i<3;i++)g.FillRectangle(dark,x+u*5,y+u*(2+i*2),u*4,u);}
  else if(kind==3){g.FillRectangle(dark,x,y+u*3,u*12,u*8);g.FillRectangle(gold,x,y+u*2,u*12,u*3);g.FillRectangle(light,x+u*5,y,u*2,u*11);g.FillRectangle(green,x+u*2,y,u*3,u*2);g.FillRectangle(green,x+u*7,y,u*3,u*2);}
  else if(kind==5){g.FillRectangle(dark,x+u,y+u,u*10,u*10);g.FillRectangle(light,x+u*2,y+u*2,u*8,u*8);g.FillRectangle(green,x+u*2,y+u*2,u*8,u*2);g.FillRectangle(gold,x+u*3,y,u,u*3);g.FillRectangle(gold,x+u*8,y,u,u*3);for(int row=0;row<2;row++)for(int col=0;col<3;col++)g.FillRectangle(dark,x+u*(3+col*2),y+u*(5+row*2),u,u);}
  else{for(int i=0;i<4;i++){g.FillRectangle(green,x+u*(1+i*3),y+u*(8-i*2),u*2,u*(3+i*2));g.FillRectangle(light,x+u*(1+i*3),y+u*(8-i*2),u*2,u);}}
 }}
}
public sealed class HallMeter : Control {
 public string Caption="",Detail="",Attributes="",Compact="";public double Fraction;public Color Accent=GuildChrome.Gold;public int IconKind;
 public Image Portrait;public Rectangle PortraitSource;public bool InsetHUD;
 public HallMeter(){SetStyle(ControlStyles.SupportsTransparentBackColor,true);DoubleBuffered=true;BackColor=Color.Transparent;Height=66;Font=GameTheme.Body(11);Margin=new Padding(4);}
 public void Activate(){OnClick(EventArgs.Empty);}
 public void DrawResource(Graphics g,Rectangle r){DrawIcon(g,new Point(r.X+5,r.Y+4),IconKind);using(var small=GameTheme.Body(10)){var label=new Rectangle(r.X+38,r.Y,r.Width-44,r.Height);var flags=TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding|TextFormatFlags.PreserveGraphicsClipping|TextFormatFlags.PreserveGraphicsTranslateTransform;var shadow=label;shadow.Offset(1,1);TextRenderer.DrawText(g,Compact,small,shadow,Color.FromArgb(31,39,29),flags);TextRenderer.DrawText(g,Compact,small,label,Color.FromArgb(255,238,188),flags);}}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;var r=Rectangle.Inflate(ClientRectangle,-2,-2);if(r.Width<8||r.Height<8)return;
  if(InsetHUD){DrawIcon(g,new Point(r.X+5,r.Y+4),IconKind);using(var small=GameTheme.Body(10)){var label=new Rectangle(r.X+38,r.Y,r.Width-44,r.Height);var flags=TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding|TextFormatFlags.PreserveGraphicsClipping|TextFormatFlags.PreserveGraphicsTranslateTransform;var shadow=label;shadow.Offset(1,1);TextRenderer.DrawText(g,Compact,small,shadow,Color.FromArgb(31,39,29),flags);TextRenderer.DrawText(g,Compact,small,label,Color.FromArgb(255,238,188),flags);}return;}
  using(var b=new SolidBrush(Color.FromArgb(28,55,48)))g.FillPolygon(b,GameTheme.Outline(r,5));using(var p=new Pen(Color.FromArgb(113,122,86)))g.DrawPolygon(p,GameTheme.Outline(r,5));
  if(Height<66&&Portrait==null){using(var small=GameTheme.Body(10))TextRenderer.DrawText(g,Compact.Length>0?Compact:Caption,small,Rectangle.Inflate(r,-6,-2),Accent,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding);return;}
  int left=r.X+8;
  if(Portrait!=null){var source=PortraitSource.IsEmpty?new Rectangle(Point.Empty,Portrait.Size):PortraitSource;float h=r.Height-8,w=h*source.Width/source.Height;g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.NearestNeighbor;g.DrawImage(Portrait,new RectangleF(r.X+8,r.Y+4,w,h),source,GraphicsUnit.Pixel);left+=(int)w+14;}
  else if(IconKind>0&&Width>160){DrawIcon(g,new Point(r.X+11,r.Y+10),IconKind);left+=36;}
  TextRenderer.DrawText(g,Caption,Font,new Rectangle(left,r.Y+3,r.Right-left-8,22),Accent,TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding);
  TextRenderer.DrawText(g,Detail,Font,new Rectangle(left,r.Y+25,r.Right-left-8,22),GuildChrome.Ivory,TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding);
  if(Attributes.Length>0&&r.Height>82)TextRenderer.DrawText(g,Attributes,Font,new Rectangle(left,r.Y+49,r.Right-left-8,22),Color.FromArgb(153,201,186),TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding);
  if(r.Height>53){var track=new Rectangle(left,r.Bottom-10,Math.Max(0,r.Right-left-8),5);using(var b=new SolidBrush(Color.FromArgb(13,33,28)))g.FillRectangle(b,track);track.Width=(int)(track.Width*Math.Max(0,Math.Min(1,Fraction)));using(var b=new SolidBrush(Accent))g.FillRectangle(b,track);}
 }
 static void DrawIcon(Graphics g,Point at,int kind){using(var fill=new SolidBrush(Color.FromArgb(205,174,102)))using(var shade=new SolidBrush(Color.FromArgb(116,94,58)))using(var light=new SolidBrush(Color.FromArgb(242,220,163))){int x=at.X,y=at.Y;
  if(kind==1){g.FillRectangle(shade,x,y+5,26,17);g.FillRectangle(fill,x+3,y+2,20,20);g.FillRectangle(light,x+7,y+5,4,14);g.FillRectangle(shade,x+16,y+8,4,8);}
  else if(kind==2){g.FillRectangle(fill,x+4,y,8,8);g.FillRectangle(fill,x,y+11,17,13);g.FillRectangle(shade,x+18,y+5,7,7);g.FillRectangle(shade,x+20,y+14,9,10);}
  else if(kind==3){g.FillRectangle(fill,x+11,y,7,26);g.FillRectangle(fill,x+3,y+8,23,9);g.FillRectangle(fill,x+7,y+17,16,6);g.FillRectangle(light,x+11,y+8,7,7);}
  else{g.FillRectangle(shade,x+2,y+3,26,22);g.FillRectangle(fill,x,y,25,22);g.FillRectangle(light,x+5,y+4,6,14);g.FillRectangle(shade,x+14,y+6,7,2);g.FillRectangle(shade,x+14,y+12,7,2);}
 }}
}
public partial class Game {
 void BuildHallManagement(Panel parent,TavernHallState s,Func<bool> paused,Action<bool> pause){
  hallRefreshAudio=null;hallSaveStudy=null;int tab=Math.Max(0,hallManagementTab),person=0,actionPage=0;
  Action render=null;render=()=>{
   hallRefreshManagement=null;while(parent.Controls.Count>0)parent.Controls[0].Dispose();
   var frame=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,BackColor=parent.BackColor};frame.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));
   frame.RowStyles.Add(new RowStyle(SizeType.Absolute,34));frame.RowStyles.Add(new RowStyle(SizeType.Absolute,parent.ClientSize.Height<460?58:76));frame.RowStyles.Add(new RowStyle(SizeType.Percent,100));frame.RowStyles.Add(new RowStyle(SizeType.Absolute,50));parent.Controls.Add(frame);
   var nav=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=7,RowCount=1};string[] names={"员工","菜单","设施","调度","奖励","账本","招募"};for(int i=0;i<7;i++){nav.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/7));int choice=i;var button=HallAction(names[i],()=>{tab=choice;render();});button.Active=tab==i;button.Font=GameTheme.Body(10);nav.Controls.Add(button,i,0);}frame.Controls.Add(nav,0,0);
   var meter=new HallMeter{Dock=DockStyle.Fill,IconKind=tab==4?4:tab==5?3:0};frame.Controls.Add(meter,0,1);
   var container=new Panel{Dock=DockStyle.Fill,BackColor=parent.BackColor};frame.Controls.Add(container,0,2);var actionStore=new Panel{Visible=false};container.Controls.Add(actionStore);var rows=HallRows(actionStore,7);rows.RowStyles[0].SizeType=SizeType.Percent;rows.RowStyles[0].Height=100;for(int i=1;i<7;i++){rows.RowStyles[i].SizeType=SizeType.Absolute;rows.RowStyles[i].Height=34;}
   var info=new HallPagedText{Dock=DockStyle.Fill,Font=GameTheme.Body(11)};rows.Controls.Add(info,0,0);var feedback=new HallPagedText{Dock=DockStyle.Fill,Font=GameTheme.Body(10)};frame.Controls.Add(feedback,0,3);
   var roster=TavernHall.Employees(s);person=Math.Max(0,Math.Min(person,roster.Count-1));var selected=roster[person];
   if(tab==0){bool helper=person>=2;string sprite=helper?"walking/"+(selected.role==0?"helper-chef-v1.png":"helper-server-v1.png"):selected.role==0?"actions/lyse-actions.png":"actions/aelia-actions.png";meter.Portrait=CachedImage(System.IO.Path.Combine(root,"assets","tavern","management",sprite));using(var sheet=new HallDiningSheet(meter.Portrait,helper?4:6))meter.PortraitSource=sheet.Frames[helper?3:0,0];frame.RowStyles[1].Height=parent.ClientSize.Height<360?78:96;}
   Action update=()=>{
    if(info.IsDisposed)return;feedback.LiveContent=s.notice;
    if(tab==0){meter.Attributes="手艺 "+selected.Craft+"   效率 "+selected.Efficiency+"   服务 "+selected.Service+"   体力 "+selected.Stamina;meter.Caption=selected.name+"  Lv."+selected.level+" · "+(selected.role==0?"厨房":"大厅");meter.Detail="成长 "+selected.xp+" / "+(selected.level>=5?"当前满级":selected.NextXp.ToString())+"   好感 "+selected.affinity;meter.Fraction=selected.level>=5?1:(double)selected.xp/Math.Max(1,selected.NextXp);info.LiveContent=EmployeeText(selected,selected.role==0)+"\n培养方向："+DirectionName(selected)+" · "+selected.training+" / 60\n工作、真题研修与心得分别记录；技能不会跳过设备条件。";}
    else if(tab==1){meter.Caption="今日菜单 · "+TavernHall.FocusNames[s.businessFocus];meter.Detail="胡萝卜 "+s.carrots+"   面粉 "+s.flour;meter.Fraction=Math.Min(1,(s.carrots+s.flour)/48.0);info.LiveContent="每份耗料 / 基础制作时间\n"+String.Join("\n",Enumerable.Range(0,4).Select(i=>TavernHall.Dishes[i]+"：胡萝卜"+TavernHall.Carrots[i]+"、面粉"+TavernHall.Flour[i]+" · "+TavernHall.CookTime[i]+"秒"))+"\n快手菜缓解厨房，复杂菜提高单份收入。\n收入 "+s.revenue+" − 采购 "+s.cost+" = 净收益 "+(s.revenue-s.cost);for(int i=0;i<4;i++){var b=rows.GetControlFromPosition(0,i+1) as VNButton;if(b!=null)b.Text=RecipeText(s,i);}}
    else if(tab==2){meter.Caption="设施与库存";meter.Detail="出餐台 "+s.upgrade+" / 2 · "+(s.stove>0?"双锅已安装":"单锅制作");meter.Fraction=(s.upgrade+s.stove)/3.0;info.LiveContent="出餐台改善送餐；双锅配合三级厨师进行双份制作。\n当前："+(s.layout==0?"左侧交接，距离较短":"右侧交接，路线较长")+"\n自动补购："+(s.autoBuy?"开启":"关闭")+" · 上限 "+s.purchaseLimit+"金币\n本日已自动采购 "+s.purchased+"金币。";}
    else if(tab==3){meter.Caption="现场调度 · 指导 "+s.boosts+" / 3";meter.Detail="厨房积压 "+s.guests.Count(g=>g.stage==2&&g.recipe!=3)+" · 待送 / 收桌 "+s.guests.Count(g=>g.stage==3||g.stage==6);meter.Fraction=s.boosts/3.0;info.LiveContent="完成有效词汇短组获得指导，选择实际经营动作。\n集中备餐：减少两次重复准备，正常耗料。\n大厅协调：优先送餐或收桌。\n安抚等候：恢复部分耐心，不凭空完成订单。\n待用指导跨日保留，满额后仍可获得研修奖励。\n"+TavernHall.Diagnosis(s);}
    else if(tab==4){meter.Caption="研修奖励箱 · 待选 "+s.rewards+" 份";meter.Detail="进度 "+s.research+" / 100 · 累计领取 "+s.rewardsClaimed+"份";meter.Fraction=s.research/100.0;info.LiveContent="营业中与打烊后学习均计入奖励。\n心得：员工经验 +12，满级不消耗。\n茶点：已招募伙伴好感 +6，重复赠礼递减；不跳过主线。\n备餐计划：开店前使用，每日一份。\n库存："+String.Join(" · ",Enumerable.Range(0,3).Select(i=>TavernHall.ItemNames[i]+" ×"+TavernHall.ItemCount(s,i)))+"\n道具目标："+selected.name+"\n未领取的奖励保留，继续学习不会丢失。";}
    else if(tab==5){meter.Caption=TavernHall.RankName(s)+" · 第 "+s.day+" 日";meter.Detail="知名度 "+s.renown+" / "+(TavernHall.NextRenown(s)==0?"最高等级":TavernHall.NextRenown(s).ToString());meter.Fraction=TavernHall.NextRenown(s)==0?1:(double)s.renown/TavernHall.NextRenown(s);info.LiveContent=s.settled?s.summary??"旧营业记录已保存，次日生成详细账本。":"今日固定 "+s.dailyVisitors+" 位，三轮 "+TavernHall.WaveCount(s,0)+" / "+TavernHall.WaveCount(s,1)+" / "+TavernHall.WaveCount(s,2)+"\n已入店 "+s.admitted+" · 完成 "+s.served+"\n"+TavernHall.Diagnosis(s)+"\n知名度根据满意接待增长，结算后次日升级。";}
    else {meter.Caption="镇民招募 · 已有 "+s.helpers.Count+" 位帮工";meter.Detail=TavernHall.CanRecruit(save)?"旧矿道主线已完成，招聘渠道开放":"推进主线：旧矿道，第一次主动出发";meter.Fraction=s.helpers.Count/2.0;info.LiveContent="镇上热门：开放1位帮工\n商路名店：开放第2位帮工\n招募费用：60金币；厨师与服务员均会实际工作。\n厨师缓解制作积压；服务员缓解送餐和收桌。\n原伙伴的培养保留，帮工可以使用心得与听力培养。\n后续主角团招募遵循实际主线，不用送礼跳过剧情。";}
   };
   Action<int,string,Action> add=(row,title,action)=>HallButton(rows,row,title,()=>{action();Persist();update();});
   if(tab==0){add(1,"切换员工  "+(person+1)+" / "+roster.Count,()=>{person=(person+1)%roster.Count;render();});add(2,"培养方向："+DirectionName(selected),()=>{selected.direction=1-selected.direction;render();});add(3,"使用实务心得（"+TavernHall.ItemCount(s,0)+"）",()=>TavernHall.UseItem(s,0,person));add(4,"分享茶点（"+TavernHall.ItemCount(s,1)+"）",()=>TavernHall.UseItem(s,1,person));add(5,"查看成长与关系",()=>s.notice=selected.affinity>=30?selected.name+"与你越来越熟悉，感谢你为酒馆付出的努力。":"继续经营和相处，伙伴关系会逐渐成长。重要故事仍由主线开放。");}
   else if(tab==1){for(int i=0;i<4;i++){int dish=i;add(i+1,RecipeText(s,i),()=>{if(s.recipes[dish].enabled&&s.recipes.Count(r=>r.enabled)==1){s.notice="至少保留一道菜单。";return;}s.recipes[dish].enabled=!s.recipes[dish].enabled;});}add(5,"经营重点："+TavernHall.FocusNames[s.businessFocus],()=>{if(s.open||s.closing){s.notice="经营重点在开店前选择。";return;}s.businessFocus=(s.businessFocus+1)%3;render();});}
   else if(tab==2){add(1,"改善出餐台 · 30金币",()=>{if(s.upgrade>=2||save.rogue.coins<30){s.notice=s.upgrade>=2?"出餐台已满级。":"金币不足，需要30金币。";return;}save.rogue.coins-=30;s.upgrade++;});add(2,"双锅炉灶 · 45金币",()=>{if(s.stove>0||save.rogue.coins<45){s.notice=s.stove>0?"双锅已安装。":"金币不足，需要45金币。";return;}save.rogue.coins-=45;s.stove=1;});add(3,"采购各8份食材 · 32金币",()=>{if(save.rogue.coins<32){s.notice="金币不足，可启用小量自动补购。";return;}save.rogue.coins-=32;s.cost+=32;s.carrots+=8;s.flour+=8;});add(4,"补购设置：开关与上限",()=>{if(s.autoBuy&&s.purchaseLimit==80)s.purchaseLimit=120;else if(s.autoBuy)s.autoBuy=false;else{s.autoBuy=true;s.purchaseLimit=80;}});add(5,"布局：暂停并切换交接位置",()=>{pause(true);s.layout=1-s.layout;s.notice="已调整合法路线；关闭管理后点击继续恢复营业。";});}
